"end\" fill=\"#1e293b\">5</text><text x=\"137.0\" y=\"88.0\" font-size=\"11\" text-anchor=\"end\" fill=\"#1e293b\">6</text><text x=\"137.0\" y=\"58.0\" font-size=\"11\" text-anchor=\"end\" fill=\"#1e293b\">7</text><text x=\"137.0\" y=\"28.0\" font-size=\"11\" text-anchor=\"end\" fill=\"#1e293b\">8</text><rect x=\"84.0\" y=\"84.0\" width=\"150\" height=\"150\" fill=\"#bfdbfe\" fill-opacity=\"0.6\" stroke=\"#1d4ed8\" stroke-width=\"2.4\"/><circle cx=\"84.0\" cy=\"234.0\" r=\"3.5\" fill=\"#1d4ed8\"/><text x=\"72.0\" y=\"250.0\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e3a8a\" font-weight=\"bold\">A</text><circle cx=\"234.0\" cy=\"234.0\" r=\"3.5\" fill=\"#1d4ed8\"/><text x=\"246.0\" y=\"250.0\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e3a8a\" font-weight=\"bold\">B</text><circle cx=\"234.0\" cy=\"84.0\" r=\"3.5\" fill=\"#1d4ed8\"/><text x=\"246.0\" y=\"78.0\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e3a8a\" font-weight=\"bold\">C</text><circle cx=\"84.0\" cy=\"84.0\" r=\"3.5\" fill=\"#1d4ed8\"/><text x=\"72.0\" y=\"78.0\" font-size=\"14\" text-anchor=\"middle\" fill=\"#1e3a8a\" font-weight=\"bold\">D</text><line x1=\"186.0\" y1=\"324.0\" x2=\"186.0\" y2=\"24.0\" stroke=\"#dc2626\" stroke-width=\"2\" stroke-dasharray=\"7 5\"/><text x=\"192.0\" y=\"36.0\" font-size=\"13\" text-anchor=\"start\" fill=\"#b91c1c\" font-weight=\"bold\">x = k</text></svg></div><p>k bir tam sayı olmak üzere denklemi x = k olan doğru kareyi iki dikdörtgene ayırmaktadır. Bu dikdörtgenlerden AD kenarını içerenin alanı, diğer dikdörtgenin alanının {{2|3}}’üdür. (Şekildeki x = k doğrusunun yeri temsilîdir.)</p><p><b>Buna göre k kaçtır?</b></p>",
